import { ensureFileExists, ensureFolderExists } from "../src/cliFiles";

test("ensureFileExists: success", async ()=>{
    await ensureFileExists("tests/res/a.txt", "This test should work!");
})

test("ensureFileExists: no name", async ()=>{
    await expect(async ()=>await ensureFileExists("", "No hint!")).rejects.toThrow("File not found, no file name defined. No hint!");
})

test("ensureFileExists: folder instead of file", async ()=>{
    await expect(async ()=>await ensureFileExists("tests/res", "No hint!")).rejects.toThrow("'tests/res' is not a file. No hint!");
})

test("ensureFolderExists: success", async ()=>{
    await ensureFolderExists("tests/res", "This test should work!");
})

test("ensureFolderExists: no name", async ()=>{
    await expect(async ()=>await ensureFolderExists("", "No hint!")).rejects.toThrow("Folder not found, no file name defined. No hint!");
})

test("ensureFolderExists: folder instead of file", async ()=>{
    await expect(async ()=>await ensureFolderExists("tests/res/a.txt", "No hint!")).rejects.toThrow("'tests/res/a.txt' is not a folder. No hint!");
})